CREATE TABLE IF NOT EXISTS spawnentry_post_velious LIKE spawnentry;
CREATE TEMPORARY TABLE era_019 (spawngroupID INT, npcID INT, PRIMARY KEY (spawngroupID, npcID));
DELETE e FROM spawnentry e JOIN era_019 x ON x.spawngroupID = e.spawngroupID AND x.npcID = e.npcID;
DROP TEMPORARY TABLE era_019;
